let draftLoaded=false;
let S, token, page='overview', cart=[], purchaseCart=[], category='All', query='', stockFilter='All', peopleFilter='customer';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupee=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((n||0)/100);
const qty=n=>Number(Number(n||0).toFixed(3)).toLocaleString('en-IN');
const businessDay=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)),today=()=>businessDay(new Date()), date=s=>new Date(s).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
const sum=(a,key)=>a.reduce((n,r)=>n+(typeof key==='function'?key(r):Number(r[key]||0)),0);
const product=id=>S.products.find(p=>p.id==id), party=id=>S.parties.find(p=>p.id==id), stock=(id,loc)=>S.stocks.find(s=>s.product_id==id&&s.location===loc)?.quantity||0;
const liveDocs=()=>S.documents.filter(d=>!d.reversed), localLocation=()=>S.settings.device_location||'Outlet';
const iconPaths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',billing:'M4 3h16v18l-4-2-4 2-4-2-4 2z M8 7h8 M8 11h8 M8 15h4',inventory:'M3 6l9-4 9 4-9 5z M3 6v12l9 4 9-4V6 M12 11v11',purchases:'M3 5h2l3 12h10l3-9H6 M9 21h.01 M18 21h.01',cafe:'M4 4h13v8a6.5 6.5 0 0 1-13 0z M17 5h2a3 3 0 0 1 0 6h-2 M2 21h19',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 3a4 4 0 1 1 0 8 M20 21v-2a4 4 0 0 0-3-3 M9 3a4 4 0 1 0 0 8a4 4 0 0 0 0-8',reports:'M4 21h17 M7 17V9 M12 17V3 M17 17v-5',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
iconPaths.notifications=iconPaths.people;iconPaths.orders=iconPaths.inventory;
const pages={overview:'Overview',billing:'Billing & invoices',inventory:'Inventory & transfers',purchases:'Purchases',cafe:'Café menu',people:'Customers & suppliers',reports:'Reports & expenses',orders:'WhatsApp orders',notifications:'WhatsApp updates',settings:'Settings & sync'};
const icon=k=>`<svg viewBox="0 0 24 24"><path d="${iconPaths[k]}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className=error?'error-toast':'';$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6500)}
const pendingRequests=new Map();
async function api(action,data={}){const key=JSON.stringify([action,data]),financial=['sale','purchase','payment','expense','transfer','adjust','reverse','purchase_order_create','purchase_order_status'].includes(action);let storageKey='',saved='';if(financial&&S){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key));storageKey='alhadiya-retry:'+billDraftKey()+':'+Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');try{saved=sessionStorage.getItem(storageKey)||''}catch{}}const requestId=pendingRequests.get(key)||saved||Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');pendingRequests.set(key,requestId);if(storageKey)try{sessionStorage.setItem(storageKey,requestId)}catch{}let r,parsed=false;try{r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Shop-Token':token,'X-Request-ID':requestId},body:JSON.stringify(data)});const body=await r.json();parsed=true;if(r.status===401){location.href='/login';throw Error('Please sign in again.')}if(!r.ok){if(r.status<500){pendingRequests.delete(key);if(storageKey)sessionStorage.removeItem(storageKey)}throw Error(body.error||'Unable to save. Review the form.')}pendingRequests.delete(key);if(storageKey)sessionStorage.removeItem(storageKey);return body}catch(e){if(!r||!parsed)throw Error('Response interrupted. Review saved records, then retry this same operation to avoid duplicates.');throw e}}

async function load(){const r=await fetch('/api/state');if(r.status===401){location.href='/login';throw Error('Please sign in again.')}if(!r.ok)throw Error('App connection interrupted. Saved records remain safe.');S=await r.json();if(!draftLoaded){restoreBillDraft();draftLoaded=true;}$('#device-badge').textContent=S.settings.device_location||'Warehouse + Outlet';$('#sync-status').textContent=S.settings.last_sync?'Last exchange: '+new Date(S.settings.last_sync).toLocaleTimeString(): (S.settings.cloud_url?'Server paired · awaiting first exchange':'Sync folder not connected');if(!S.online&&(!S.web_user||S.web_user.role==='owner')&&S.settings.node_mode==='unified'&&!$('#node-location')){const select=document.createElement('select');select.id='node-location';select.style.cssText='width:125px;padding:6px';select.innerHTML=['Warehouse','Outlet'].map(l=>`<option>${l}</option>`).join('');select.onchange=async()=>{try{await api(S.web_user?'location':'settings',S.web_user?{location:select.value}:{device_location:select.value});cart=[];await load()}catch(e){toast(e.message,true)}};$('.header-right').prepend(select)}if($('#node-location'))$('#node-location').value=S.settings.device_location||'Warehouse';render()}
async function mutate(action,data,message){const r=await api(action,data);await load();if(message)toast(message);return r}
function navTo(name){if(!pageAllowed(name))return toast('Your role does not allow this screen.',true);page=name;query='';category='All';render();window.scrollTo(0,0)}
function pageAllowed(name){const r=S?.web_user?.role||'owner';return r==='owner'||r==='manager'?!(['settings','notifications'].includes(name)&&r!=='owner'):r==='cashier'?['overview','billing','people','staff'].includes(name):['overview','people','staff'].includes(name)}
function canOperate(action){const r=S?.web_user?.role||'owner';return r==='owner'||r==='manager'&&action!=='backup'||r==='cashier'&&['sale','party','expense'].includes(action)}
function render(){if(!S)return;$('#nav').innerHTML=Object.entries(pages).filter(([k])=>pageAllowed(k)).map(([k,v])=>`<button class="${page===k?'active':''}" onclick="navTo('${k}')">${icon(k)}<span>${v}</span></button>`).join('');$('#page-label').textContent=pages[page];$('#main').innerHTML=({planning:planningPage,orders:ordersPage,notifications:notificationsPage,overview:overview,billing:billing,inventory:inventory,purchases:purchases,cafe:cafe,people:people,reports:reports,settings:settings})[page]();bindPage()}
const heading=(tag,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const empty=text=>`<div class="empty">${text}</div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${!rows.length?empty('No records yet. Add your first entry to get started.'):''}</div>`;
const selectOptions=(rows,selected)=>rows.map(r=>`<option value="${esc(r.id)}" ${String(r.id)===String(selected)?'selected':''}>${esc(r.name)}</option>`).join('');
const symbol=c=>({'Cold drinks':'🥤','Water':'◈','Packaged water':'◈','Juices':'🍊','Energy drinks':'ϟ','Ice cream':'🍦','Snacks':'▧','Coffee':'☕','Tea & coffee':'☕','Mojitos':'🍃','Ingredients':'◌','Dairy & milk':'🥛'}[c]||'▣');
function overview(){const sales=liveDocs().filter(d=>d.kind==='sale'&&businessDay(d.date)===today()), docs=liveDocs().filter(d=>d.kind==='sale');const low=S.products.filter(p=>p.kind!=='recipe'&&(p.price>0||p.cost>0||p.stock>0)&&p.stock<=p.minimum),totalSales=sum(sales,'total');return heading('BUSINESS AT A GLANCE','A good day starts here.','Everything happening at your trading warehouse and café outlet.',`${canOperate('backup')?'<button class="btn secondary" onclick="runBackup()">↓ Back up data</button>':''}${canOperate('sale')?'<button class="btn" onclick="navTo(\'billing\')">＋ New bill <small>F2</small></button>':''}`)+
`${S.settings.demo?'<div class="notice">Sample shop data is loaded. These are illustrative products, prices and recipes. Use a separate clean database for live trading.</div>':''}${S.sync_errors.length?'<div class="help">Sync needs attention: '+S.sync_errors.length+' transaction(s) are waiting. Open Settings to review them.</div>':''}
<div class="welcome-banner"><div><strong>Chill. Refresh. Enjoy. Always.</strong><p>Cold drinks, everyday essentials & a little café happiness.</p></div><div class="banner-decoration">✦ AH</div></div>
<div class="stats">${stat('Today’s sales',rupee(totalSales),'₹',sales.length+' bills recorded today')}${stat('Inventory value',rupee(sum(S.products,p=>p.stock*p.cost)),'▣','Across warehouse & outlet')}${stat('Customer dues',rupee(sum(S.parties.filter(p=>p.kind==='customer'),'balance')),'↗','Outstanding customer credit')}${stat('Low-stock products',low.length,'◷',low.length?'Review your reorder list':'Your shelves are in good shape')}</div>
<div class="dashboard-grid"><div class="card"><div class="card-head"><div><h2>Sales this week</h2><p>Your last 7 days, across both locations</p></div><span class="pill">${docs.length} total bills</span></div>${chart(docs)}</div><div class="card"><div class="card-head"><div><h2>Your business, together</h2><p>Two locations. One clear picture.</p></div></div><div class="mix-item"><div class="mix-icon">▣</div><div><strong>Trading warehouse</strong><small>${S.stocks.filter(s=>s.location==='Warehouse'&&s.quantity>0).length} stocked SKUs · direct customer billing</small></div><b>${rupee(sum(S.stocks.filter(s=>s.location==='Warehouse'),s=>s.quantity*(product(s.product_id)?.cost||0)))}</b></div><div class="mix-item"><div class="mix-icon">▤</div><div><strong>Café / shop outlet</strong><small>Takeaway café & packaged-goods billing</small></div><b>${rupee(sum(S.stocks.filter(s=>s.location==='Outlet'),s=>s.quantity*(product(s.product_id)?.cost||0)))}</b></div><div class="mix-item"><div class="mix-icon">☕</div><div><strong>Micro café</strong><small>${S.products.filter(p=>p.kind==='recipe').length} menu items · ingredient tracking</small></div><button class="text-btn" onclick="navTo('cafe')">View menu →</button></div><div style="padding:10px 23px 22px"><div class="help" style="margin:0">${S.settings.gst_enabled?'GST billing is enabled. Prices include applicable tax.':'GST is available. Add your registration details in Settings to enable tax invoices.'}</div></div></div></div>
<div class="dashboard-grid"><div class="card"><div class="card-head"><h2>Recent invoices</h2><button class="text-btn" onclick="invoiceList()">View all →</button></div>${documentTable(S.documents.filter(d=>d.kind==='sale').slice(0,5))}</div><div class="card"><div class="card-head"><h2>Stock to watch</h2><button class="text-btn" onclick="navTo('inventory')">View stock →</button></div>${low.length?low.slice(0,5).map(p=>`<div class="mix-item"><div class="mix-icon">${symbol(p.category)}</div><div><strong>${esc(p.name)}</strong><small>Reorder at ${qty(p.minimum)} ${esc(p.unit)}</small></div><span class="pill warn">${qty(p.stock)} left</span></div>`).join(''):empty('No low-stock alerts right now.')}</div></div>${!S.products.length?'<div class="notice">Start with Settings, add products and opening warehouse stock, then transfer stock to the outlet. You can also load sample data from Settings to explore.</div>':''}`}
function stat(label,value,ico,foot){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${ico}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function chart(docs){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=businessDay(d);return {label:d.toLocaleDateString('en-IN',{weekday:'short'}),value:sum(docs.filter(s=>businessDay(s.date)===key),'total')}});const max=Math.max(...days.map(d=>d.value),100);return `<div class="chart"><div class="chart-note">${rupee(sum(days,'value'))} <span style="color:#9da491">in the last 7 days</span></div><svg viewBox="0 0 600 180" preserveAspectRatio="none">${[20,65,110,155].map(y=>`<line x1="0" x2="600" y1="${y}" y2="${y}" stroke="#eef0e8" stroke-dasharray="4 5"/>`).join('')}${days.map((d,i)=>`<rect x="${30+i*81}" y="${155-d.value/max*130}" width="37" height="${Math.max(d.value/max*130,2)}" rx="4" fill="${i===6?'#bc984f':'#d7e3d3'}"><title>${d.label}: ${rupee(d.value)}</title></rect>`).join('')}</svg><div class="chart-labels">${days.map(d=>`<span>${d.label}</span>`).join('')}</div></div>`}
function documentTable(docs){return table(['Invoice','Customer / supplier','Amount','Status',''],docs.map(d=>`<tr><td><strong>${esc(d.id)}</strong><small>${date(d.date)} · ${esc(d.location)}</small></td><td>${esc(party(d.party_id)?.name||'Walk-in customer')}<small>${esc(d.payment)}</small></td><td>${rupee(d.total)}</td><td><span class="pill ${d.reversed?'red':d.paid<d.total?'warn':''}">${d.reversed?'Reversed':d.paid<d.total?'Part paid':'Paid'}</span></td><td><button class="text-btn" onclick="viewInvoice('${esc(d.id)}')">View →</button></td></tr>`))}
function billing(){const cats=['All','Café menu',...new Set(S.products.filter(p=>p.kind!=='ingredient').map(p=>p.category))];return heading('POINT OF SALE','Let’s make a sale.','Quick billing for cold drinks, café favourites and everyday essentials.',`<button class="btn secondary" onclick="invoiceList()">▤ Invoice history</button>`)+`<div class="pos-layout"><div><div class="toolbar"><div class="search" style="width:100%"><input id="product-search" placeholder="Search product or scan barcode…  F3" value="${esc(query)}"></div></div><div class="tabs">${cats.map(c=>`<button class="${category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div id="product-results">${productCards()}</div><div class="help">F2: New bill · F3: Barcode search · F8: Checkout<br>Stock is deducted from ${esc(localLocation())}. ${S.settings.node_mode==='unified'?'Every node can bill and manage stock according to staff permissions.':S.settings.admin_device_id?isMainPC()?'This PC sells the unallocated balance.':'This till sells only its assigned stock allowance.':'Assign and pair this PC in Settings before live use.'} Cases convert to the pack quantity.</div></div><div class="card cart"><div class="cart-head"><h2>Current bill <span style="float:right;font-size:10px;color:#9a9f93">${esc(localLocation())}</span></h2><div style="display:flex;gap:6px;margin-bottom:8px"><input id="customer-mobile" type="tel" placeholder="Customer mobile (optional)"><button class="btn secondary small" onclick="findCustomerMobile()">Find</button></div><select id="sale-party" onchange="window.saleParty=this.value;window.priceTier=party(this.value)?.price_tier||'retail';render()"><option value="">Walk-in customer</option>${selectOptions(S.parties.filter(p=>p.kind==='customer'),window.saleParty)}</select><select style="margin-top:8px" onchange="window.priceTier=this.value;render()"><option value="retail" ${window.priceTier!=='wholesale'?'selected':''}>Retail price</option><option value="wholesale" ${window.priceTier==='wholesale'?'selected':''}>Wholesale price</option></select></div><div id="cart-items">${cartRows()}</div><div class="cart-totals"><div class="total-row"><span>Subtotal</span><span id="subtotal">${rupee(cartTotal())}</span></div><div class="total-row"><span>Discount ₹</span><input id="discount" type="number" min="0" step="0.01" value="${window.saleDiscount||0}" style="width:100px;padding:7px" oninput="window.saleDiscount=this.value;updateTotal()"></div><div class="total-row grand"><span>Total</span><span id="grand-total">${rupee(Math.max(0,cartTotal()-Math.round((window.saleDiscount||0)*100)))}</span></div><p style="font-size:10px">${S.settings.gst_enabled?'GST and applicable cess included':'GST not collected · registration not enabled'}</p></div><div class="cart-pay"><button class="btn gold" onclick="checkout()" ${!cart.length?'disabled':''}>Checkout & save bill <small>F8</small></button><button class="text-btn" style="width:100%;margin-top:13px" onclick="clearCart()">Clear bill</button></div></div></div>`}
function productCards(){const products=S.products.filter(p=>p.kind!=='ingredient'&&p.price>0&&(category==='All'||category==='Café menu'&&p.kind==='recipe'||p.category===category)&&(`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.size}`.toLowerCase().includes(query.toLowerCase())));return products.length?`<div class="product-grid">${products.map(p=>`<button class="product-card" onclick="addCart(${p.id})"><span class="product-symbol">${symbol(p.category)}</span><strong>${esc(p.name)}</strong><small>${p.kind==='recipe'?'Made fresh':qty(billStock(p.id))+' '+esc(p.unit)+' available'}</small><b>${rupee(p.price)}</b></button>`).join('')}</div>`:empty('No matching products. Add products in Inventory, or sync from the warehouse.')}
function salePrice(p){return window.priceTier==='wholesale'&&p.wholesale_price>0?p.wholesale_price:p.price}
function isMainPC(){return !S.settings.device_location||S.settings.device_id===S.settings.admin_device_id}
function billStock(id,loc=localLocation()){if(S.settings.node_mode==='unified'||!S.settings.admin_device_id)return stock(id,loc);if(isMainPC())return Math.max(0,stock(id,loc)-sum(S.allocations.filter(a=>a.product_id==id&&a.location===loc),'quantity'));return S.allocations.find(a=>a.device_id===S.settings.device_id&&a.product_id==id&&a.location===loc)?.quantity||0}
function cartTotal(){return sum(cart,l=>Math.round(salePrice(product(l.id))*l.quantity))}
function cartRows(){return cart.length?`<div class="cart-items">${cart.map(l=>{const p=product(l.id);return `<div class="cart-line"><div class="cart-line-top"><strong>${esc(p.name)}</strong><span>${rupee(salePrice(p)*l.quantity)}</span></div><div class="cart-line-bottom"><div class="qty-control"><button onclick="changeQty(${l.id},${l.quantity-1})">−</button><input type="number" min="0.001" step="any" value="${l.quantity}" onchange="changeQty(${l.id},this.value)"><button onclick="changeQty(${l.id},${l.quantity+1})">＋</button></div><small>${esc(p.unit)} ${p.pack>1?`<button class="text-btn" onclick="changeQty(${l.id},${l.quantity+p.pack})">＋ case (${qty(p.pack)})</button>`:''}</small></div></div>`}).join('')}</div>`:empty('Your bill is empty.<br>Tap a product or scan a barcode.')}
function addCart(id){if(window.saleTradeOrder)return toast('This basket belongs to a WhatsApp order. Clear it to start a separate sale.',true);const p=product(id);if(p.price<=0)return toast('Set a selling price in Inventory first.',true);if(p.kind!=='recipe'&&billStock(id)<=0)return toast('No stock at this location. Transfer stock from the warehouse first.',true);const l=cart.find(l=>l.id===id);if(p.kind!=='recipe'&&(l?.quantity||0)+1>billStock(id))return toast('Quantity exceeds available stock at this location.',true);if(l)l.quantity++;else cart.push({id,quantity:1});render()}
function changeQty(id,n){if(window.saleTradeOrder)return toast('Review quantities on the WhatsApp order before billing.',true);n=Number(n);if(!Number.isFinite(n))return;if(product(id).kind!=='recipe'&&n>billStock(id))return toast('Quantity exceeds available stock at this location.',true);if(n<=0)cart=cart.filter(l=>l.id!==id);else cart.find(l=>l.id===id).quantity=n;render()}
function clearCart(){window.saleTradeOrder='';cart=[];window.saleDiscount=0;render()}
function updateTotal(){$('#grand-total').textContent=rupee(Math.max(0,cartTotal()-Math.round((window.saleDiscount||0)*100)))}
function openModal(title,body,footer=''){const d=$('#modal');$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-content"><div id="form-error" class="error" role="alert"></div>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal()}
function closeModal(){$('#modal').close()}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function dropdown(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const v=typeof o==='string'?o:o.value,n=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`}).join('')}</select></div>`}
function formModal(title,body,onSubmit,button='Save'){openModal(title,`<form id="edit-form">${body}<button type="submit" hidden></button></form>`,`<button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn gold" id="form-submit" onclick="document.getElementById('edit-form').requestSubmit()">${button}</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();$('#form-error').textContent='';$('#form-submit').disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await onSubmit(data);if($('#edit-form')===e.target)closeModal()}catch(err){$('#form-error').textContent=err.message}finally{if($('#form-submit'))$('#form-submit').disabled=false}}}
function checkout(){if(!cart.length)return;const total=cartTotal()-Math.round((window.saleDiscount||0)*100);if(total<0)return toast('Discount exceeds total.',true);formModal('Complete sale',`<div class="report-number">${rupee(total)}</div><p>${esc(party(window.saleParty)?.name||'Walk-in customer')} · ${esc(localLocation())}</p><div class="help">Save the bill before collecting or printing. UPI and card entries record payment; they do not charge the customer.</div><div class="form-grid">${dropdown('Payment method','payment',['Cash','UPI','Card','Bank'],'Cash')}${field('Amount received ₹','paid',total/100,'number','min="0" step="0.01" required')}${field('Place of supply (state code)','supply_state',party(window.saleParty)?.gstin?.slice(0,2)||S.settings.state,'text','pattern="[0-9]{2}" maxlength="2"')}${field('Reference / note','reference')}</div><small>For customer credit, select a customer and enter the amount received. Change is not counted as revenue.</small>`,async data=>{const r=await mutate('sale',{...data,price_tier:window.priceTier||'retail',party_id:window.saleParty||null,location:localLocation(),discount:window.saleDiscount||0,trade_order_id:window.saleTradeOrder||'',items:cart.map(l=>({product_id:l.id,quantity:l.quantity}))});cart=[];saveBillDraft();window.saleTradeOrder='';window.saleDiscount=0;render();closeModal();viewInvoice(r.id);toast('Sale saved. Stock and customer ledger updated.')},'Save invoice')}
function invoiceList(){openModal('Invoice history',`<div class="search" style="margin-bottom:20px"><input id="invoice-search" placeholder="Find invoice or customer"></div><div id="invoice-results">${documentTable(S.documents.filter(d=>d.kind==='sale'))}</div>`);$('#invoice-search').oninput=e=>{$('#invoice-results').innerHTML=documentTable(S.documents.filter(d=>d.kind==='sale'&&(`${d.id} ${party(d.party_id)?.name||''}`).toLowerCase().includes(e.target.value.toLowerCase())))};}
function receiptHTML(d){const snap=d.snapshot,shop=snap.shop,items=snap.items,gst=sum(items,'gst_amount'),cess=sum(items,'cess_amount');return `<div class="receipt-preview"><div class="receipt-shop"><h2>${esc(shop.name)}</h2><p>${esc(shop.address)}</p><small>${shop.phone?'Tel: '+esc(shop.phone)+'<br>':''}${shop.gst_enabled?'GSTIN: '+esc(shop.gstin):'GST not collected'}</small><h3 style="margin:17px 0 4px">${d.reversed?'REVERSED · ':''}${d.kind==='purchase'?'PURCHASE RECORD':shop.gst_enabled?'TAX INVOICE':'SALE RECEIPT'}</h3></div><p style="font-size:11px">No: <b>${esc(d.id)}</b><br>${date(d.date)} ${new Date(d.date).toLocaleTimeString('en-IN')} · ${esc(d.location)}<br>${d.kind==='purchase'?'Supplier':'Customer'}: ${esc(snap.party.name||'Walk-in customer')}${snap.party.gstin?'<br>GSTIN: '+esc(snap.party.gstin):''}${snap.party.address?'<br>'+esc(snap.party.address):''}<br>Place of supply: ${esc(snap.supply_state)} ${shop.gst_enabled?'· '+esc(snap.tax_type):''}</p>${table(['Item','Qty','Rate','Total'],items.map(i=>`<tr><td>${esc(i.name)}<small>${i.hsn?'HSN/SAC '+esc(i.hsn):''}${shop.gst_enabled?' · GST '+i.gst+'%'+(i.cess?' / Cess '+i.cess+'%':''):''}</small></td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${rupee(i.price)}</td><td>${rupee(i.total)}</td></tr>`))}<div class="total-row"><span>Discount included</span><span>${rupee(d.discount)}</span></div>${shop.gst_enabled?`<div class="total-row"><span>Taxable value</span><span>${rupee(d.total-d.tax)}</span></div>${snap.tax_type==='IGST'?`<div class="total-row"><span>IGST</span><span>${rupee(gst)}</span></div>`:`<div class="total-row"><span>CGST</span><span>${rupee(sum(items,'cgst_amount'))}</span></div><div class="total-row"><span>SGST</span><span>${rupee(sum(items,'sgst_amount'))}</span></div>`}${cess?`<div class="total-row"><span>Cess</span><span>${rupee(cess)}</span></div>`:''}`:''}<div class="total-row grand"><span>Total</span><span>${rupee(d.total)}</span></div><div class="total-row"><span>Paid · ${esc(d.payment)}</span><span>${rupee(d.paid)}</span></div><div class="total-row"><span>Credit at issue</span><span>${rupee(d.total-d.paid)}</span></div>${d.reference?`<p style="font-size:10px">Reference: ${esc(d.reference)}</p>`:''}<p style="text-align:center;font-size:11px;margin-top:24px">Thank you for shopping with us.<br>Chill · Refresh · Enjoy · Always</p><p style="text-align:center;font-size:9px;margin-top:7px">Authorised signatory: __________________</p></div>`}
function viewInvoice(id){const d=S.documents.find(d=>d.id===id);openModal(d.kind==='sale'?'Invoice details':'Purchase record',receiptHTML(d),`${!d.reversed&&canOperate('reverse')?`<button class="btn danger small" onclick="reverseDocument('${esc(id)}')">Reverse full ${d.kind==='sale'?'bill':'purchase'}</button>`:''}<button class="btn secondary" onclick="closeModal()">Close</button><button class="btn gold" onclick="printInvoice('${esc(id)}')">Print / Save PDF</button>`)}
function printInvoice(id){$('#print-area').innerHTML=receiptHTML(S.documents.find(d=>d.id===id));let st=$('#print-format');if(!st){st=document.createElement('style');st.id='print-format';document.head.appendChild(st)}const width=S.settings.printer;st.textContent=width==='A4'?'@media print{#print-area{max-width:190mm;margin:auto}}':`@media print{#print-area{width:${width==='58'?'48':'70'}mm;margin:0}#print-area .receipt-preview td{font-size:9px}} @page{size:${width}mm auto;margin:4mm}`;window.print()}
function reverseDocument(id){const d=S.documents.find(d=>d.id===id);formModal('Reverse full document',`<div class="help">This restores the original stock movements and reverses outstanding credit. ${rupee(d.paid)} paid by ${esc(d.payment)} must be refunded or reconciled outside the app. This is a full internal reversal; a statutory GST credit note is not generated.</div>${field('Reason','reason','','text','required')}`,async data=>{const r=await mutate('reverse',{id,...data},'Document reversed. Refund to reconcile: '+rupee(d.paid));return r},'Reverse document')}
function inventory(){const locs=['All','Warehouse','Outlet'], filtered=S.products.filter(p=>(`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.size}`.toLowerCase().includes(query.toLowerCase())));return heading('STOCK CONTROL','Every bottle accounted for.','Track packaged products and café ingredients at both locations.',`<button class="btn secondary" onclick="transferForm()">⇄ Stock transfer</button><button class="btn" onclick="productForm()">＋ Add product</button>`)+`<div class="toolbar"><div class="search"><input id="inventory-search" placeholder="Search name or barcode…" value="${esc(query)}"></div><div class="actions"><button class="btn secondary small" onclick="adjustForm()">Adjust / wastage</button><button class="btn secondary small" onclick="movementList()">Movement history</button><button class="btn secondary small" onclick="importForm()">Import CSV</button><button class="btn secondary small" onclick="loadCatalogue()">Starter catalogue</button><button class="btn secondary small" onclick="exportStock()">Export CSV</button></div></div><div class="tabs">${locs.map(l=>`<button class="${stockFilter===l?'active':''}" onclick="stockFilter='${l}';render()">${l==='All'?'Both locations':l}</button>`).join('')}</div><div class="card" id="inventory-results">${inventoryTable(filtered)}</div><div class="help">One base unit per product: bottles, packs, ml or grams. Cases convert to the configured number of base units. Expiry is tracked per SKU in this version; separate batches need separate SKUs.</div>`}
function inventoryTable(products){return table(['Product','Category','Warehouse','Outlet','Selling price','GST / cess','Stock status',''],products.map(p=>{const count=stockFilter==='All'?p.stock:stock(p.id,stockFilter);return `<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)}${p.barcode?' · ▥ '+esc(p.barcode):''} · ${p.kind==='recipe'?'Made fresh':esc(p.unit)}${p.expiry?' · Exp '+esc(p.expiry):''}</small></td><td>${esc(p.category)}</td><td>${p.kind==='recipe'?'—':qty(stock(p.id,'Warehouse'))}</td><td>${p.kind==='recipe'?'Made fresh':qty(stock(p.id,'Outlet'))}</td><td>${rupee(p.price)}</td><td>${p.gst}%${p.cess?' + '+p.cess+'%':''}</td><td><span class="pill ${p.kind!=='recipe'&&count<=p.minimum?'warn':''}">${p.kind==='recipe'?'Made fresh':!p.price&&!p.cost&&!p.stock?'Needs setup':count<=p.minimum?'Low stock':'In stock'}</span></td><td><button class="text-btn" onclick="productForm(${p.id})">Edit</button></td></tr>`}))}
function productForm(id,cafeItem=false){const p=id?product(id):{category:cafeItem?'Coffee':'Cold drinks',unit:cafeItem?'cup':'bottle',kind:cafeItem?'recipe':'stock',price:0,cost:0,gst:0,cess:0,minimum:cafeItem?0:12,pack:cafeItem?1:24};const categories=['Cold drinks','Packaged water','Juices','Energy drinks','Ice cream','Snacks','Tea & coffee','Dairy & milk','Mojitos','Coffee','Ingredients'];if(!categories.includes(p.category))categories.push(p.category);formModal(id?'Edit product':'Add product',`<div class="form-grid">${field('Product name','name',p.name,'text','required')}${field('Internal SKU','sku',p.sku,'text','required')}${field('Manufacturer barcode (scan pack)','barcode',p.barcode)}${field('Brand','brand',p.brand)}${field('Pack size','size',p.size,'text','list="size-presets"')}${field('Packaging','packaging',p.packaging,'text','list="pack-presets"')}${field('MRP ₹ (0 if not applicable)','mrp',(p.mrp||0)/100,'number','min="0" step="0.01"')}${field('Wholesale price ₹ per base unit','wholesale_price',(p.wholesale_price||0)/100,'number','min="0" step="0.01"')}${dropdown('Category','category',categories,p.category)}${dropdown('Product type','kind',[{value:'stock',label:'Packaged stock'},{value:'ingredient',label:'Café ingredient'},{value:'recipe',label:'Café menu item (made fresh)'}],p.kind)}${field('Base unit (bottle, ml, g, cup)','unit',p.unit,'text','required')}${field('Base units per case / pack','pack',p.pack,'number','min="1" step="any" required')}${field('Selling price ₹ (tax inclusive)','price',p.price/100,'number','min="0" step="0.01" required')}${field('Purchase cost ₹ per base unit','cost',p.cost/100,'number','min="0" step="0.01" required')}${field('GST rate %','gst',p.gst,'number','min="0" max="100" step="any"')}${field('Cess rate % (if applicable)','cess',p.cess,'number','min="0" max="100" step="any"')}${field('HSN / SAC','hsn',p.hsn)}${field('Low-stock threshold','minimum',p.minimum,'number','min="0" step="any"')}${field('Expiry date (optional)','expiry',p.expiry,'date')}${!id?field('Opening stock in base units','stock',0,'number','min="0" step="any"')+dropdown('Opening stock location','location',['Warehouse','Outlet'],'Warehouse'):''}</div><datalist id="size-presets">${['100 ml','150 ml','160 ml','180 ml','200 ml','250 ml','300 ml','330 ml','350 ml','400 ml','450 ml','473 ml','500 ml','600 ml','650 ml','750 ml','1 L','1.2 L','1.25 L','1.5 L','1.75 L','2 L','2.25 L','3 L','5 L','10 L','20 L','25 g','50 g','75 g','100 g','150 g','200 g','250 g','500 g','1 kg','2 kg','5 kg','Small pack','Regular pack'].map(v=>`<option value="${v}">`).join('')}</datalist><datalist id="pack-presets">${['PET bottle','Glass bottle','Can','Carton','Cup','Sachet','Pack','Tub','Jar','Case','Crate'].map(v=>`<option value="${v}">`).join('')}</datalist><label class="check"><input type="checkbox" name="tax_verified" ${p.tax_verified?'checked':''}> HSN/SAC and tax rate have been checked for this product</label><div class="help">Rates depend on classification and registration. Use current supplier invoices and your accountant’s advice. Café ingredients must use the same units as the recipe.</div>`,data=>mutate('product',{...data,id:id||null},id?'Product updated.':'Product added.'))}
function transferForm(){formModal('Transfer stock between locations',`${dropdown('Product','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name}))) }<div class="form-grid">${dropdown('Dispatch from','source',['Warehouse','Outlet'],S.settings.device_location||'Warehouse')}${dropdown('Send to','target',['Warehouse','Outlet'],S.settings.device_location==='Outlet'?'Warehouse':'Outlet')}${field('Quantity in base units','quantity','','number','min="0.001" step="any" required')}${field('Transfer note','note','Stock transfer')}</div><div class="help">Stock leaves the source and is allocated to the destination. The receiving PC sees it after sync. Only dispatch goods you have actually sent.</div>`,data=>mutate('transfer',data,'Transfer saved. Sync both PCs to exchange the stock movement.'))}
function adjustForm(){formModal('Stock adjustment / wastage',`${dropdown('Product','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name})))}${dropdown('Location','location',['Warehouse','Outlet'],localLocation())}${field('Quantity change (negative for wastage)','quantity','','number','step="any" required')}${field('Reason','note','','text','required')}<div class="help">Examples: −2 bottles damaged, +3 bottles found during stock count. The reason is kept in the movement history.</div>`,data=>mutate('adjust',data,'Stock adjustment recorded.'))}
function movementList(){openModal('Recent stock movements',table(['Date','Product','Location','Change','Reason'],S.movements.map(m=>`<tr><td>${date(m.date)}<small>${esc(m.reference)}</small></td><td>${esc(product(m.product_id)?.name)}</td><td>${esc(m.location)}</td><td style="color:${m.quantity<0?'#a06e57':'#527558'}">${m.quantity>0?'+':''}${qty(m.quantity)}</td><td>${esc(m.note)}</td></tr>`)))}
function purchases(){return heading('SUPPLIER PURCHASES','Stock coming in.','Receive bottles, cases and ingredients. Keep supplier dues in view.',`<button class="btn" onclick="purchaseForm()">＋ Receive purchase</button>`)+`<div class="stats">${stat('Purchases recorded',rupee(sum(liveDocs().filter(d=>d.kind==='purchase'),'total')),'↓','All recorded supplier purchases')}${stat('Supplier dues',rupee(sum(S.parties.filter(p=>p.kind==='supplier'),'balance')),'↗','Outstanding purchase credit')}${stat('Suppliers',S.parties.filter(p=>p.kind==='supplier').length,'♙','Your purchase partners')}${stat('Warehouse stock value',rupee(sum(S.stocks.filter(s=>s.location==='Warehouse'),s=>s.quantity*(product(s.product_id)?.cost||0))),'▣','At average acquisition cost')}</div><div class="card"><div class="card-head"><h2>Purchase history</h2><button class="text-btn" onclick="partyForm('supplier')">＋ Add supplier</button></div>${documentTable(S.documents.filter(d=>d.kind==='purchase'))}</div>`}
function purchaseForm(){if(!S.parties.some(p=>p.kind==='supplier'))return partyForm('supplier');purchaseCart=[];formModal('Receive supplier purchase',`${dropdown('Supplier','party_id',S.parties.filter(p=>p.kind==='supplier').map(p=>({value:p.id,label:p.name})))}<div class="form-grid">${dropdown('Receive at','location',['Warehouse','Outlet'],S.settings.device_location||'Warehouse')}${field('Supplier invoice reference','reference','','text','required')}</div><label>Purchase items</label><div class="help">Choose a product, then enter bottles/packs or use its case button. Unit cost is the cost for one bottle/pack, including tax.</div><div id="purchase-lines"></div><button type="button" class="btn secondary small" onclick="addPurchaseLine()">＋ Add item</button><div class="form-grid" style="margin-top:20px">${dropdown('Payment method','payment',['Cash','UPI','Card','Bank'],'Cash')}${field('Amount paid ₹','paid',0,'number','min="0" step="0.01" required')}</div><div class="help" id="purchase-total">Add the products on the supplier’s invoice. Stock increases and the unpaid amount becomes a supplier due.</div>`,async data=>{const items=Array.from(document.querySelectorAll('.purchase-line')).map(el=>({product_id:el.querySelector('select').value,quantity:el.querySelector('[data-qty]').value,price:el.querySelector('[data-price]').value}));await mutate('purchase',{...data,items},'Purchase saved. Stock and supplier ledger updated.');});addPurchaseLine()}
function addPurchaseLine(){const el=document.createElement('div');el.className='purchase-line form-grid';el.style.cssText='padding:13px;background:#f7f8f4;border-radius:6px;margin:10px 0';el.innerHTML=`<div class="field span2"><select onchange="this.closest('.purchase-line').querySelector('[data-price]').value=product(this.value).cost/100;purchaseTotal()">${selectOptions(S.products.filter(p=>p.kind!=='recipe'))}</select></div><div><label>Quantity (base units)</label><input data-qty type="number" min="0.001" step="any" value="1" oninput="purchaseTotal()" required></div><div><label>Unit cost ₹ (incl. tax)</label><input data-price type="number" min="0" step="0.01" value="${(S.products.find(p=>p.kind!=='recipe')?.cost||0)/100}" oninput="purchaseTotal()" required></div><div class="actions"><button type="button" class="text-btn" onclick="const e=this.closest('.purchase-line');e.querySelector('[data-qty]').value=product(e.querySelector('select').value).pack;purchaseTotal()">Set 1 case / pack</button><button type="button" class="text-btn" onclick="this.closest('.purchase-line').remove();purchaseTotal()">Remove</button></div>`;$('#purchase-lines').appendChild(el);purchaseTotal()}
function purchaseTotal(){const total=Array.from(document.querySelectorAll('.purchase-line')).reduce((n,el)=>n+Math.round(Number(el.querySelector('[data-qty]').value)*Number(el.querySelector('[data-price]').value)*100),0);$('#purchase-total').textContent='Purchase total: '+rupee(total)+' · Enter the amount paid; the remainder becomes supplier credit.'}
function cafe(){const menu=S.products.filter(p=>p.kind==='recipe');return heading('TAKE & GO CAFÉ','A little café happiness.','Manage fresh drinks and the ingredients behind every cup.',`<button class="btn secondary" onclick="openCafePOS()">Open café POS</button><button class="btn" onclick="productForm(null,true)">＋ Add menu item</button>`)+`<div class="notice">Selling a café item deducts its configured ingredients from café stock. Receive ingredients at the warehouse, then transfer them to the outlet before serving.</div><div class="product-grid">${menu.map(p=>{const r=S.recipes.filter(r=>r.product_id===p.id);const cost=sum(r,r=>r.quantity*(product(r.ingredient_id)?.cost||0));const available=r.length?Math.min(...r.map(r=>Math.floor(stock(r.ingredient_id,'Outlet')/r.quantity))):0;return `<div class="card"><div class="card-content"><span style="font-size:33px">${symbol(p.category)}</span><h3 style="margin:16px 0 9px">${esc(p.name)}</h3><p>${rupee(p.price)} <span style="font-size:11px">per ${esc(p.unit)}</span></p><p style="font-size:11px;margin-top:8px">Ingredient cost: ${rupee(cost)}<br>${available} servings available at outlet</p><div class="help">${r.length?r.map(r=>esc(product(r.ingredient_id)?.name)+' · '+qty(r.quantity)+' '+esc(product(r.ingredient_id)?.unit)).join('<br>'):'Set ingredients per serving before billing.'}</div><button class="btn secondary small" onclick="recipeForm(${p.id})">Set ingredients</button></div></div>`}).join('')}</div>${!menu.length?empty('Add a café menu item, then set ingredients per serving.'):''}<div class="card" style="margin-top:24px"><div class="card-head"><h2>Café ingredients</h2><button class="text-btn" onclick="navTo('inventory')">Manage stock →</button></div>${inventoryTable(S.products.filter(p=>p.kind==='ingredient'))}</div>`}
function recipeForm(id){if(!S.products.some(p=>p.kind==='ingredient'))return toast('Add café ingredients in Inventory first.',true);formModal('Ingredients per serving · '+esc(product(id).name),`<p style="font-size:12px;margin-bottom:18px">Quantities for one ${esc(product(id).unit)}. Include milk, syrup, coffee and packaging if you track it.</p><div id="recipe-lines"></div><button type="button" class="btn secondary small" onclick="addRecipeLine()">＋ Ingredient</button><div class="help">Quantities must use the ingredient’s base unit. For example: 200 ml soda + 30 ml mint syrup for one mojito.</div>`,async()=>{const items=Array.from(document.querySelectorAll('.recipe-line')).map(el=>({ingredient_id:el.querySelector('select').value,quantity:el.querySelector('input').value}));await mutate('recipe',{product_id:id,items},'Ingredient quantities saved.')});const current=S.recipes.filter(r=>r.product_id===id);if(current.length)current.forEach(r=>addRecipeLine(r.ingredient_id,r.quantity));else addRecipeLine()}
function addRecipeLine(id,quantity=1){const el=document.createElement('div');el.className='recipe-line';el.innerHTML=`<select>${selectOptions(S.products.filter(p=>p.kind==='ingredient').map(p=>({...p,name:p.name+' ('+p.unit+')'})),id)}</select><input type="number" min="0.001" step="any" value="${quantity}" required><button type="button" onclick="this.parentElement.remove()">×</button>`;$('#recipe-lines').appendChild(el)}
function people(){return heading('PEOPLE & LEDGERS','Good relationships. Clear accounts.','Keep customer credit and supplier payments easy to follow.',canOperate('party')?`<button class="btn" onclick="partyForm('${peopleFilter}')">＋ Add ${peopleFilter}</button>`:'')+`<div class="tabs"><button class="${peopleFilter==='customer'?'active':''}" onclick="peopleFilter='customer';render()">Customers</button><button class="${peopleFilter==='supplier'?'active':''}" onclick="peopleFilter='supplier';render()">Suppliers</button></div><div class="card">${table(['Name','Contact','GSTIN','Outstanding',''],S.parties.filter(p=>p.kind===peopleFilter).map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></td><td>${esc(p.phone)||'—'}</td><td>${esc(p.gstin)||'—'}</td><td><span class="pill ${p.balance?'warn':''}">${rupee(p.balance)}</span></td><td><button class="text-btn" onclick="ledger(${p.id})">Profile & ledger</button>${canOperate('party')?`<button class="text-btn" onclick="partyForm('${peopleFilter}',${p.id})">Edit profile</button>`:''}${p.balance&&canOperate('payment')?`<button class="btn secondary small" onclick="paymentForm(${p.id})">${p.kind==='customer'?'Collect':'Pay'}</button>`:''}</td></tr>`))}</div>`}
function partyForm(kind='customer',id){const p=id?party(id):{};formModal((id?'Edit ':'Add ')+kind,`<div class="form-grid">${field('Name / business name','name',p.name,'text','required')}${field('Phone','phone',p.phone,'tel')}${field('Email','email',p.email,'email')}${field('GSTIN (optional)','gstin',p.gstin,'text','maxlength="15"')}${field('Billing address','address',p.address)}${dropdown('Preferred price tier','price_tier',['retail','wholesale'],p.price_tier||'retail')}${field('Credit limit ₹ (0 = no preset limit)','credit_limit',(p.credit_limit||0)/100,'number','min="0" step="0.01"')}${field('Customer notes','notes',p.notes)}${field('WhatsApp consent evidence (new consent or changed mobile)','whatsapp_consent_note','','text','placeholder="How, when and for which messages did the customer agree?" maxlength="500"')}</div><label class="check"><input type="checkbox" name="whatsapp_opt_in" ${p.whatsapp_opt_in?'checked':''}> Customer agreed to WhatsApp receipts and payment notifications</label><label class="check"><input type="checkbox" name="whatsapp_marketing_opt_in" ${p.whatsapp_marketing_opt_in?'checked':''}> Customer separately agreed to promotional WhatsApp offers</label><div class="help">Editing a profile preserves its purchases, payments and outstanding balance. Credit limits follow staff permissions. Invoice details remain as issued.</div>`,data=>mutate('party',{...data,id:id||null,kind},id?'Profile updated.':kind+' added.'))}
function paymentForm(id){const p=party(id);formModal(p.kind==='customer'?'Record customer payment':'Record supplier payment',`<h3>${esc(p.name)}</h3><p style="margin-bottom:20px">Outstanding: ${rupee(p.balance)}</p>${field('Payment amount ₹','amount',p.balance/100,'number','min="0.01" step="0.01" required')}${dropdown('Payment method','method',['Cash','UPI','Card','Bank'],'Cash')}${field('Reference / note','note')}`,data=>mutate('payment',{...data,party_id:id},'Payment recorded. Ledger updated.'))}
function ledger(id){const p=party(id),docs=S.documents.filter(d=>d.party_id===id),pay=S.payments.filter(r=>r.party_id===id);openModal('Ledger · '+esc(p.name),`<div class="report-number">${rupee(p.balance)}</div><p style="margin-bottom:23px">${p.kind==='customer'?'Receivable from customer':'Payable to supplier'}</p><div class="notice">${esc(p.phone)||'No phone'} · ${esc(p.email)||'No email'}<br>${esc(p.address)}<br>${p.gstin?'GSTIN: '+esc(p.gstin)+'<br>':''}Preferred pricing: ${esc(p.price_tier||'retail')} · Credit limit: ${p.credit_limit?rupee(p.credit_limit):'Not preset'}<br>${esc(p.notes)}</div>${table(['Date','Entry','Credit / due','Paid / settled'],[...docs.map(d=>({date:d.date,entry:d.id+(d.reversed?' · REVERSED':''),due:d.reversed?0:d.total-d.paid,paid:d.reversed?0:d.paid})),...pay.map(r=>({date:r.date,entry:'Payment · '+r.method,due:-r.amount,paid:r.amount}))].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<tr><td>${date(r.date)}</td><td>${esc(r.entry)}</td><td>${rupee(r.due)}</td><td>${rupee(r.paid)}</td></tr>`))}`)}
let reportFrom='',reportTo='';
function reportDocuments(){return liveDocs().filter(d=>(!reportFrom||d.date.slice(0,10)>=reportFrom)&&(!reportTo||d.date.slice(0,10)<=reportTo))}
function reports(){const docs=reportDocuments(),sales=docs.filter(d=>d.kind==='sale'),purchases=docs.filter(d=>d.kind==='purchase'),ids=new Set(sales.map(d=>d.id)),cost=sum(S.lines.filter(l=>ids.has(l.document_id)),'cost'),expenses=S.expenses.filter(e=>(!reportFrom||e.date.slice(0,10)>=reportFrom)&&(!reportTo||e.date.slice(0,10)<=reportTo)),revenue=sum(sales,d=>d.total-d.tax),gstLines=sales.flatMap(d=>d.snapshot.items.map(i=>({...i,doc:d})));return heading('BUSINESS REPORTS','Know where you stand.','Sales, purchases, operating expenses and tax records in one place.',`<button class="btn secondary" onclick="exportSales()">↓ Sales CSV</button><button class="btn" onclick="expenseForm()">＋ Record expense</button>`)+`<div class="toolbar"><p style="font-size:12px">Reports include saved, unreversed transactions.</p><div class="range"><input id="report-from" type="date" value="${reportFrom}"><span>to</span><input id="report-to" type="date" value="${reportTo}"><button class="btn secondary small" onclick="reportFrom=$('#report-from').value;reportTo=$('#report-to').value;render()">Apply</button></div></div><div class="stats">${stat('Sales (including GST)',rupee(sum(sales,'total')),'₹',sales.length+' invoices in selected period')}${stat('Purchases',rupee(sum(purchases,'total')),'↓','Recorded purchase invoice value')}${stat('Operating expenses',rupee(sum(expenses,'amount')),'↗',expenses.length+' expense entries')}${stat('Estimated contribution',rupee(revenue-cost-sum(expenses,'amount')),'◴','Sales ex tax − recorded cost − expenses')}</div><div class="help">Contribution is a management estimate, not statutory profit. Recorded costs include purchase taxes; café ITC eligibility and formal accounting are not inferred. For GST filing, have your accountant review the exported sales records.</div><div class="dashboard-grid"><div class="card"><div class="card-head"><h2>GST sales summary</h2><button class="text-btn" onclick="exportGST()">Export details →</button></div>${table(['Tax category','Taxable value','GST','Cess'],[...new Set(gstLines.map(l=>l.gst+'|'+l.cess+'|'+l.doc.snapshot.tax_type))].map(k=>{const ls=gstLines.filter(l=>l.gst+'|'+l.cess+'|'+l.doc.snapshot.tax_type===k);return `<tr><td>${ls[0].gst}% · ${esc(ls[0].doc.snapshot.tax_type)}${ls[0].cess?' + '+ls[0].cess+'% cess':''}</td><td>${rupee(sum(ls,'taxable'))}</td><td>${rupee(sum(ls,'gst_amount'))}</td><td>${rupee(sum(ls,'cess_amount'))}</td></tr>`}))}</div><div class="card"><div class="card-head"><h2>Expenses</h2></div>${table(['Date','Expense','Amount'],expenses.map(e=>`<tr><td>${date(e.date)}</td><td>${esc(e.name)}<small>${esc(e.method)}</small></td><td>${rupee(e.amount)}</td></tr>`))}</div></div><div class="card"><div class="card-head"><h2>Payment methods at invoice issue</h2></div>${table(['Method','Sales received','Purchases paid'],['Cash','UPI','Card','Bank'].map(m=>`<tr><td>${m}</td><td>${rupee(sum(sales.filter(d=>d.payment===m),'paid'))}</td><td>${rupee(sum(purchases.filter(d=>d.payment===m),'paid'))}</td></tr>`))}</div>`}
function expenseForm(){formModal('Record shop expense',`${field('Expense description','name','','text','required')}<div class="form-grid">${field('Amount ₹','amount','','number','min="0.01" step="0.01" required')}${dropdown('Paid by','method',['Cash','UPI','Card','Bank'],'Cash')}</div>`,data=>mutate('expense',data,'Expense recorded.'))}
function settings(){const s=S.settings;return heading('YOUR SHOP, EVERYWHERE','Your business on this node.','Every PC has the same functions. Location selects where a transaction takes place.')+`<form id="settings-form"><div class="settings-layout"><div class="card"><div class="card-head"><h2>Business & GST</h2></div><div class="card-content"><div class="form-grid">${field('Business name','name',s.name,'text','required')}${field('Phone','phone',s.phone,'tel')}${field('Business address','address',s.address)}${field('GSTIN','gstin',s.gstin,'text','maxlength="15"')}${field('State code (Karnataka = 29)','state',s.state,'text','pattern="[0-9]{2}" maxlength="2" required')}${field('Invoice prefix','invoice_prefix',s.invoice_prefix,'text','pattern="[A-Z0-9]{1,2}" maxlength="2" required')}</div><label class="check"><input type="checkbox" name="gst_enabled" ${s.gst_enabled?'checked':''}> Enable regular-registration GST</label><div class="help">Verify GST classification with your accountant. Statutory credit notes, composition billing, IRN, e-way bills and portal filing are not included.</div>${dropdown('Print layout','printer',[{value:'80',label:'80 mm thermal receipt'},{value:'58',label:'58 mm thermal receipt'},{value:'A4',label:'A4 invoice'}],s.printer)}</div></div><div class="card"><div class="card-head"><h2>This node & sync</h2></div><div class="card-content"><div class="notice">Purchases, payments, stock, catalogue, café recipes, credit bills and business settings are available on every node, including offline. Sync exchanges saved changes. Competing offline stock or ledger transactions can require reconciliation; review any sync errors.</div>${field('PC name','device_name',s.device_name)}${dropdown('Default transaction location','device_location',['Warehouse','Outlet'],s.device_location||'Warehouse')}${s.cloud_url?`<p>Connected to ${esc(s.cloud_url)}</p><button type="button" class="btn secondary small" onclick="serverAddressForm()">Update server address</button><button type="button" class="btn secondary small" onclick="disconnectServerForm()">Finish sync & disconnect server</button>`:`<button type="button" class="btn gold" onclick="cloudPairForm()">Connect to online business</button>${s.cloud_business_id?'<button type="button" class="btn secondary small" onclick="serverAddressForm()">Resume existing server connection</button>':''}${field('Shared sync folder (alternative to server)','sync_folder',s.sync_folder,'text','placeholder="C:\\Users\\Owner\\OneDrive\\AlHidayaShared"')}`}<div style="margin-top:15px">${field('Additional backup folder (optional)','backup_folder',s.backup_folder)}</div><p style="font-size:11px">Last exchange: ${s.last_sync?esc(new Date(s.last_sync).toLocaleString()):'Not yet'}<br>Last verified backup: ${s.last_backup?esc(new Date(s.last_backup).toLocaleString()):'Not yet'}<br>Automatic exchange every 30 seconds while the launcher is open.</p><div class="actions"><button type="button" class="btn secondary small" onclick="runSync()">↻ Sync now</button><button type="button" class="btn secondary small" onclick="runBackup()">Back up now</button><a class="btn secondary small" href="/api/backup-download" download="AlHidaya-backup.sqlite3">Download database</a><a class="btn secondary small" href="/api/backup-bundle" download>Download backup with photos</a><button type="button" class="btn secondary small" onclick="restoreForm()">Restore backup</button></div></div></div></div><div id="settings-error" class="error"></div><div class="actions" style="margin-top:20px"><button type="submit" class="btn gold">Save settings</button><button type="button" class="btn secondary" onclick="closeApp()">Close app safely</button>${!S.products.length?'<button type="button" class="btn secondary" onclick="loadDemo()">Explore sample shop</button>':''}</div></form>${S.sync_errors.length?`<div class="card" style="margin-top:22px"><div class="card-head"><h2>Sync needs review</h2></div>${table(['Transaction','Issue'],S.sync_errors.map(e=>`<tr><td>${esc(e.id)}</td><td style="white-space:normal">${esc(e.message)}</td></tr>`))}</div>`:''}`}
function bindPage(){if(page==='billing'){if($('#product-search')){$('#product-search').oninput=e=>{query=e.target.value;$('#product-results').innerHTML=productCards()};$('#product-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const p=S.products.find(p=>p.sku===e.target.value.trim()||p.barcode===e.target.value.trim());if(p&&p.kind!=='ingredient'){addCart(p.id);query='';$('#product-search').value='';$('#product-results').innerHTML=productCards();$('#product-search').focus()}else toast('Barcode not found. Add the manufacturer’s barcode as the SKU.',true)}}}document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()})}if(page==='inventory')$('#inventory-search').oninput=e=>{query=e.target.value;$('#inventory-results').innerHTML=inventoryTable(S.products.filter(p=>(p.name+' '+p.sku+' '+p.barcode).toLowerCase().includes(query.toLowerCase())))};if(page==='settings')$('#settings-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.gst_enabled=e.target.gst_enabled.checked;await mutate('settings',data,'Settings saved.')}catch(err){$('#settings-error').textContent=err.message}finally{button.disabled=false}}}
async function runSync(){try{const r=await mutate('sync');toast(r.message,r.pending>0)}catch(e){toast(e.message,true)}}
async function runBackup(){try{const r=await mutate('backup');toast(r.message)}catch(e){toast(e.message,true)}}
function loadDemo(){formModal('Explore sample data',`<div class="help">This adds sample stock, suppliers and café recipes. The database will be marked as a sample shop. For real trading, start with a separate empty data folder.</div>`,async()=>{await mutate('demo',{},'Sample shop loaded.');navTo('overview')},'Load sample shop')}
function loadCatalogue(){formModal('Add Indian starter catalogue',`<p>379 editable templates covering major beverage brands, common pack sizes, snacks, dairy, ice cream and café ingredients.</p><div class="help">These are product templates, not a current manufacturer catalogue. Availability and packaging vary by market. Existing SKUs stay as entered. New records start with zero stock and price, blank barcodes and unconfirmed tax rates. Scan real packs and enter your supplier’s details before trading.</div>`,async()=>{const r=await mutate('catalog');toast(r.count+' new product templates added.')},'Add catalogue')}
function parseCSV(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV has an unclosed quoted field.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);const headers=rows.shift()?.map(h=>h.trim().toLowerCase());if(!headers?.includes('name')||!headers?.includes('sku'))throw Error('CSV must contain name and sku columns. Download the template.');return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()]).filter(([h,v])=>v!=='')))}
function importForm(){formModal('Import products from CSV',`<p style="margin-bottom:18px">Import up to 1,000 rows at a time. Matching SKUs update product details; new SKUs create products. Existing stock is preserved.</p><button type="button" class="btn secondary small" onclick="downloadImportTemplate()">↓ Download CSV template</button><div class="field" style="margin-top:20px"><label for="import-file">Product CSV file</label><input id="import-file" type="file" accept=".csv,text/csv" required></div><div class="help">Required: name, sku, category and unit. Supported: barcode, brand, size, packaging, kind, price, cost, mrp, wholesale_price, gst, cess, hsn, tax_verified, pack, minimum, expiry, opening_stock and location. Price/cost values are rupees. Use tax_verified=true only after checking classification and rates. Opening stock is allowed only on new products.</div>`,async()=>{const file=$('#import-file').files[0];if(!file)throw Error('Choose a CSV file.');if(file.size>1000000)throw Error('CSV exceeds 1 MB.');const rows=parseCSV(await file.text());const r=await mutate('import_products',{rows});toast(r.count+' products imported.')},'Import products')}
function downloadImportTemplate(){csv('AlHidaya-product-import-template.csv',['name','sku','barcode','brand','size','packaging','category','unit','kind','price','cost','mrp','wholesale_price','gst','cess','hsn','tax_verified','pack','minimum','expiry','opening_stock','location'],[['Example beverage 250 ml','MY-SKU-001','','Example brand','250 ml','PET bottle','Cold drinks','bottle','stock',0,0,0,0,0,0,'','false',24,12,'',0,'Warehouse']])}
function closeApp(){formModal('Close Al Hadiya Traders',`<p>A verified local backup will be created before the app closes. You can then close the browser tab or run a newer Setup.exe to update.</p>`,async()=>{const r=await api('shutdown');closeModal();$('#main').innerHTML=heading('SESSION CLOSED','Shop data saved.',esc(r.message));toast(r.message)},'Back up & close')}
function csv(name,headers,rows){const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportStock(){csv('AlHidaya-stock.csv',['SKU','Product','Unit','Warehouse','Outlet','Total stock','Selling price','Recorded cost','GST %','Cess %','Expiry'],S.products.map(p=>[p.sku,p.name,p.unit,stock(p.id,'Warehouse'),stock(p.id,'Outlet'),p.stock,p.price/100,p.cost/100,p.gst,p.cess,p.expiry]))}
function exportSales(){csv('AlHidaya-sales.csv',['Invoice','Date','Location','Customer','Total','Tax','Paid at issue','Payment','Discount'],reportDocuments().filter(d=>d.kind==='sale').map(d=>[d.id,d.date,d.location,d.snapshot.party.name||'Walk-in',d.total/100,d.tax/100,d.paid/100,d.payment,d.discount/100]))}
function exportGST(){csv('AlHidaya-GST-sales.csv',['Invoice','Date','Customer GSTIN','Place of supply','HSN/SAC','Product','Quantity','GST rate','Cess rate','Taxable value','CGST','SGST','IGST','Cess','Total'],reportDocuments().filter(d=>d.kind==='sale').flatMap(d=>d.snapshot.items.map(i=>{const igst=d.snapshot.tax_type==='IGST';return [d.id,d.date,d.snapshot.party.gstin||'',d.snapshot.supply_state,i.hsn,i.name,i.quantity,i.gst,i.cess,i.taxable/100,(i.cgst_amount||0)/100,(i.sgst_amount||0)/100,igst?i.gst_amount/100:0,i.cess_amount/100,i.total/100]})))}
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key==='F2'){e.preventDefault();navTo('billing')}if(e.key==='F3'){e.preventDefault();navTo('billing');$('#product-search')?.focus()}if(e.key==='F8'&&page==='billing'){e.preventDefault();checkout()}});
function tick(){$('#clock').textContent=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})+' · '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,30000);
(async()=>{try{token=(await (await fetch('/api/session')).json()).token;await load()}catch(e){$('#main').innerHTML=heading('APP CONNECTION','Open the local app first.',esc(e.message))}})();
setInterval(async()=>{if(!S||$('#modal').open||cart.length||page==='settings'||page==='billing')return;try{await load()}catch{}},30000);

function findCustomerMobile(){const value=$('#customer-mobile').value.replace(/\D/g,'').slice(-10);if(value.length!==10)return toast('Enter a 10-digit mobile number.',true);const found=S.parties.filter(p=>p.kind==='customer'&&p.phone.replace(/\D/g,'').slice(-10)===value);if(found.length===1){window.saleParty=found[0].id;window.priceTier=found[0].price_tier;render();toast('Customer selected: '+found[0].name)}else if(found.length>1){toast('Multiple profiles use this mobile. Choose the correct customer from the list.',true)}else{partyForm('customer');$('#f-phone').value=value;toast('Create an optional customer profile. Walk-in billing remains available.')}}
function notificationsPage(){
 const s=S.settings, campaigns=S.campaigns||[], templates=S.whatsapp_templates||[];
 if(S.online&&S.web_user?.role!=='owner')return heading('WHATSAPP','Owner access required','An owner manages recipients, templates and campaigns.');
 return heading('WHATSAPP UPDATES','Keep everyone informed.','Internal alerts, customer receipts and approved outreach.',`<button class="btn secondary" onclick="whatsappSettings()">Configure sender</button><button class="btn" onclick="sendNotifications()">Process queue</button>`)+`
 <div class="notice">${s.whatsapp_enabled?'Automation enabled on this sender.':'Notifications paused.'} ${S.whatsapp_token_configured?'Sender credential saved.':'Configure a sender credential.'}<br>Internal recipients: ${S.internal_contacts.filter(r=>r.opt_in).length} · Branded internal template: ${esc(templates.find(t=>t.name===s.whatsapp_internal_template)?.status||'Not refreshed')}<br>${S.whatsapp_webhook_configured?'Webhook credentials saved; subscribe the public endpoint in Meta to receive delivery updates.':'Configure the hosted webhook for delivery status and STOP replies.'} Configure one active sender per business to avoid duplicate messages.</div>
 <div class="card" style="margin-top:20px"><div class="card-head"><div><h2>Customer outreach</h2><p>Separate promotional consent · owner approves every campaign</p></div><button class="text-btn" onclick="campaignForm()">＋ Create campaign</button></div>${table(['Campaign','Audience','Schedule / status',''],campaigns.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.template)} · ${esc(c.language)}</small></td><td>${JSON.parse(c.recipients).length} customer(s)</td><td>${esc(c.status)}<small>${c.scheduled?esc(new Date(c.scheduled).toLocaleString('en-IN')):'After approval'}</small></td><td><button class="text-btn" onclick="campaignPreview('${esc(c.id)}')">Review</button> ${c.status!=='cancelled'?`<button class="text-btn" onclick="cancelCampaign('${esc(c.id)}')">Cancel</button>`:''}</td></tr>`))}</div>${catalogueManagement()}
 <div class="card" style="margin-top:20px"><div class="card-head"><div><h2>Meta templates</h2><p>Prepare text or image campaigns. Meta approval is required before sending.</p></div><button class="text-btn" onclick="refreshTemplates()">Refresh from Meta</button></div>${table(['Name / language','Category','Meta status','Format'],templates.map(t=>`<tr><td>${esc(t.name)}<small>${esc(t.language)}</small></td><td>${esc(t.category)}</td><td>${esc(t.status)}</td><td>${t.supported?(t.header_format==='IMAGE'?'Image + ':'')+(t.parameter_count||0)+' text parameters':'Unsupported format'}</td></tr>`))}<div class="help">Create and submit templates in WhatsApp Manager. Meta must approve them before real customer messages can be sent. <button class="text-btn" onclick="webhookSettings()">Configure delivery webhook</button></div></div>
 <div class="card" style="margin-top:20px"><div class="card-head"><div><h2>Internal recipients</h2><p>Owner, warehouse and café staff · individually opted-in numbers</p></div><button class="text-btn" onclick="internalContact()">＋ Add recipient</button></div>${table(['Name','Mobile','Notifications',''],S.internal_contacts.map(r=>`<tr><td>${esc(r.name)}</td><td>+${esc(r.phone)}</td><td>${r.opt_in?'Enabled':'Opted out'}</td><td><button class="text-btn" onclick="internalContact(${r.id})">Edit</button></td></tr>`))}</div>
 <div class="card" style="margin-top:20px"><div class="card-head"><h2>Recent notification queue</h2><button class="text-btn" onclick="load()">Refresh</button></div>${table(['Created','Type / mobile','Status','Details'],S.notifications.map(n=>`<tr><td>${date(n.created)}</td><td>${esc(n.kind)}<small>+${esc(n.phone)}</small></td><td><span class="pill ${['failed','uncertain'].includes(n.status)?'warn':''}">${esc(n.status)}</span><small>${n.attempts} attempt(s)</small></td><td style="white-space:normal">${esc(n.detail||'Waiting for sender connectivity or scheduled time')}</td></tr>`))}</div>`
}
function campaignForm(){
 const templates=(S.whatsapp_templates||[]).filter(t=>t.category==='MARKETING'&&t.supported);
 if(!templates.length)return toast('Refresh Meta templates before preparing a campaign.',true);
 formModal('Draft customer campaign',`${field('Campaign name','name','','text','required maxlength="100"')}<label>Marketing template<select name="template_key">${templates.map((t,i)=>`<option value="${i}">${esc(t.name)} (${esc(t.language)}) · ${esc(t.status)} · ${t.header_format==='IMAGE'?'Image':'Text'}</option>`).join('')}</select></label>${imagePicker('Campaign image','asset_id','')}${field('Offer text','offer','','text','required maxlength="800"')}${dropdown('Customer audience','audience',['All opted-in customers','Retail customers','Wholesale customers'],'All opted-in customers')}${field('Schedule (optional, your browser local time)','scheduled','','datetime-local')}<div class="help">Only customers with separate promotional consent are included. Duplicate mobile numbers receive one message. Saving creates a draft; no messages are sent until you review and approve it. Image templates require an image. Templates without placeholders use fixed Meta text; the offer field then remains an internal note.</div>`,async data=>{
 const t=templates[Number(data.template_key)];
 const ids=S.parties.filter(p=>p.kind==='customer'&&p.whatsapp_marketing_opt_in&&(!data.audience||data.audience==='All opted-in customers'||p.price_tier===(data.audience==='Retail customers'?'retail':'wholesale'))).map(p=>p.id);
 const r=await mutate('campaign_create',{name:data.name,offer:data.offer,template:t.name,language:t.language,customer_ids:ids,asset_id:data.asset_id,scheduled:data.scheduled?new Date(data.scheduled).toISOString():''},'Campaign saved as draft.');
 setTimeout(()=>campaignPreview(r.id),50);
 });
}
function campaignPreview(id){
 const c=(S.campaigns||[]).find(c=>c.id===id);if(!c)return;
 const audience=JSON.parse(c.recipients),t=(S.whatsapp_templates||[]).find(t=>t.name===c.template&&t.language===c.language);
 const preview=(t?.body||'{{1}} · {{2}} · {{3}}').replaceAll('{{1}}',audience[0]?.name||'Customer').replaceAll('{{2}}',S.settings.name).replaceAll('{{3}}',c.offer);
 openModal('Review campaign',`<p><strong>${esc(c.name)}</strong> · ${audience.length} customers</p>${c.asset_id?`<img src="/media/${esc(c.asset_id)}" alt="Campaign image" style="width:100%;max-height:340px;object-fit:contain;border-radius:12px">`:''}<div class="notice" style="white-space:pre-wrap">${esc(preview)}</div><p>${c.scheduled?'Scheduled: '+esc(new Date(c.scheduled).toLocaleString('en-IN')):'Queue after owner approval; sends when automation is enabled and online.'}</p><p>${audience.slice(0,10).map(r=>`${esc(r.name)} (+${esc(r.phone)})`).join('<br>')}${audience.length>10?'<br>…':''}</p><div class="help">Consent is checked again before each send. Reply STOP opts out when the hosted webhook is subscribed. Meta messaging charges may apply.</div>${c.status==='draft'?`<button class="btn" onclick="approveCampaign('${esc(c.id)}')">Approve ${audience.length} recipients</button>`:`<span class="pill">${esc(c.status)}</span>`}`);
}
async function approveCampaign(id){try{const r=await mutate('campaign_approve',{id,confirmed:true});closeModal();toast(r.queued+' messages queued.')}catch(e){toast(e.message,true)}}
async function cancelCampaign(id){if(!confirm('Cancel messages that have not started sending?'))return;try{await mutate('campaign_cancel',{id},'Pending messages cancelled.')}catch(e){toast(e.message,true)}}
async function refreshTemplates(){try{const r=await mutate('whatsapp_templates',{});toast(r.count+' templates refreshed.')}catch(e){toast(e.message,true)}}
function webhookSettings(){formModal('Hosted WhatsApp webhook',`<div class="notice">Callback URL: ${esc(S.online?location.origin+'/webhooks/whatsapp':'Use your hosted app HTTPS address + /webhooks/whatsapp')}</div>${field('Meta app secret (blank keeps saved)','app_secret','','password','autocomplete="new-password"')}${field('Verification token you choose (16+ characters)','verify_token','','password','autocomplete="new-password"')}<div class="help">Find the app secret in Meta app settings. After saving, enter this callback URL and the same verification token in Meta, then subscribe the messages field. These credentials stay on this sender and are excluded from sync.</div>`,data=>mutate('whatsapp_webhook',data,'Webhook credentials saved. Configure the subscription in Meta.'))}
function internalContact(id){const r=S.internal_contacts.find(r=>r.id===id)||{};formModal('Internal WhatsApp recipient',`${field('Staff / owner name','name',r.name,'text','required')}${field('Mobile number','phone',r.phone,'tel','required')}<label class="check"><input type="checkbox" name="opt_in" ${r.opt_in?'checked':''}> This recipient agreed to internal WhatsApp updates</label>`,data=>mutate('internal_contact',{...data,id},'Recipient saved.'))}
function whatsappSettings(){const s=S.settings;formModal('WhatsApp Business automation',`${s.whatsapp_pause_reason?'<div class="notice">'+esc(s.whatsapp_pause_reason)+'</div>':''}<label class="check"><input type="checkbox" name="whatsapp_enabled" ${s.whatsapp_enabled?'checked':''}> Enable notifications on this sender</label><div class="form-grid">${field('Meta sender phone-number ID','whatsapp_phone_id',s.whatsapp_phone_id)}${field('WhatsApp Business Account ID','whatsapp_waba_id',s.whatsapp_waba_id)}${dropdown('Notification timezone','whatsapp_timezone',['Asia/Kolkata','UTC'],s.whatsapp_timezone||'Asia/Kolkata')}${field('Supported Graph API version','whatsapp_api_version',s.whatsapp_api_version,'text','placeholder="Use version from your Meta console"')}${field('Template language code','whatsapp_language',s.whatsapp_language)}${field('Access token (blank keeps existing)','token','','password','autocomplete="new-password"')}${field('Approved invoice template','whatsapp_invoice_template',s.whatsapp_invoice_template)}${field('Approved payment template','whatsapp_payment_template',s.whatsapp_payment_template)}${field('Approved internal update template','whatsapp_internal_template',s.whatsapp_internal_template)}${field('Daily summary time (selected notification timezone)','whatsapp_daily_time',s.whatsapp_daily_time,'time')}</div>${['low_stock','transfers','purchases','sales','payments','expenses','reversals','profiles','catalogue','stock','recipes','orders'].map(k=>`<label class="check"><input type="checkbox" name="whatsapp_${k}" ${s['whatsapp_'+k]?'checked':''}> ${k.replaceAll('_',' ')}</label>`).join('')}<div class="help">Keep sending disabled while a Meta restriction or review is pending. Use approved body-only templates with exactly three text parameters: invoice = customer, invoice number, amount; payment = customer, amount, note; internal = business, update type, summary. Configure matching language codes in Meta. Recipients must opt in. Meta account setup and messaging charges apply. The token stays on this PC; Windows protects it for your Windows account.</div>`,data=>{for(const key of ['whatsapp_enabled','whatsapp_low_stock','whatsapp_transfers','whatsapp_purchases','whatsapp_sales','whatsapp_payments','whatsapp_expenses','whatsapp_reversals','whatsapp_profiles','whatsapp_catalogue','whatsapp_stock','whatsapp_recipes','whatsapp_orders'])data[key]=data[key]==='on';return mutate('whatsapp_settings',data,'WhatsApp configuration saved.')})}
async function sendNotifications(){try{const r=await api('whatsapp_send');await load();toast(r.message||'Processed '+r.processed+' queued notification(s).')}catch(e){toast(e.message,true)}}

function cloudPairForm(){formModal('Connect this PC to your online business',`${field('Server HTTPS address','url','https://alhidaya.3.110.148.105.sslip.io','url','required')}${field('One-time pairing code','code','','password','required autocomplete="off"')}${field('Name for this PC','peer_name',S.settings.device_name||'Warehouse Till','text','required')}<label class="check"><input type="checkbox" name="replace_sample" required> This PC contains only sample/test records. Replace them with the server records after a backup.</label><div class="help">Existing local records are backed up first. This flow does not merge real trading records. Pairing codes expire after 10 minutes. Location is a default, not a permissions restriction. Every paired node can perform all business operations. Use a permanent server for live business.</div>`,async data=>{data.replace_sample=data.replace_sample==='on';data.name=data.peer_name;delete data.peer_name;const r=await api('cloud_pair',data);cart=[];window.saleParty='';await load();toast(r.message)},'Back up & connect')}

function serverAddressForm(){formModal('Update server address',`${field('Server HTTPS address','url',S.settings.cloud_url,'url','required')}<div class="help">Use this when the same server’s IP or domain changes. Your existing records, pending transactions and credential are preserved. The app verifies that the address belongs to the same business before changing it.</div>`,data=>mutate('cloud_address',data,'Server address updated. Click Sync now.'))}

function imagePicker(label,name,value){return `<div class="field"><label>${label}</label><select name="${esc(name)}" id="f-${esc(name)}" onchange="const p=document.getElementById('preview-${esc(name)}');p.src='/media/'+this.value;p.style.display=this.value?'block':'none'"><option value="">No image</option>${(S.media_assets||[]).map(a=>`<option value="${esc(a.id)}" ${a.id===value?'selected':''}>${esc(a.name)}</option>`).join('')}</select><input type="file" accept="image/png,image/jpeg" onchange="uploadImage(this,'${esc(name)}')"><div class="help">JPEG or PNG, up to 5 MB. Upload a product photograph or campaign creative.</div><img id="preview-${esc(name)}" ${value?'src="/media/'+esc(value)+'"':''} style="max-width:180px;max-height:160px;border-radius:10px;${value?'':'display:none'}"></div>`}
async function uploadImage(input,name){const file=input.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Use an image under 5 MB.');const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});const result=await api('media_upload',{name:file.name,content:encoded});const select=document.getElementById('f-'+name);const option=document.createElement('option');option.value=result.id;option.textContent=file.name;select.append(option);select.value=result.id;const preview=document.getElementById('preview-'+name);preview.src='/media/'+result.id;preview.style.display='block';toast('Image uploaded.')}catch(e){toast(e.message,true)}}
function catalogueManagement(){const rows=S.catalogue_products||[],orders=S.catalogue_orders||[];return `<div class="card" style="margin-top:20px"><div class="card-head"><div><h2>Photo catalogue & order requests</h2><p>Publish chosen products with real photos and prices.</p></div><button class="text-btn" onclick="catalogueSettings()">Catalogue settings</button><button class="text-btn" onclick="catalogueProduct()">＋ Publish product</button></div><div class="help">${S.online?`<a href="/catalogue" target="_blank">Open customer catalogue →</a>`:'Publish on your hosted sender to make the catalogue available to customers.'} This shop catalogue works independently of Meta Commerce approval.</div>${table(['Product','Photo','Published',''],rows.map(r=>`<tr><td>${esc(product(r.product_id)?.name)}</td><td><img src="/media/${esc(r.asset_id)}" style="width:60px;height:60px;object-fit:cover;border-radius:8px"></td><td>${r.published?'Yes':'Draft'}</td><td><button class="text-btn" onclick="catalogueProduct(${r.product_id})">Edit</button></td></tr>`))}<div class="card-head"><h2>Customer order requests</h2></div>${table(['Request / customer','Estimated total','Status',''],orders.map(o=>`<tr><td>${esc(o.id)}<small>${esc(o.name)} · +${esc(o.phone)}</small></td><td>${rupee(o.total)}</td><td>${esc(o.status)}</td><td><button class="text-btn" onclick="catalogueOrder('${esc(o.id)}')">Review</button></td></tr>`))}</div>`}
function catalogueProduct(pid){const r=(S.catalogue_products||[]).find(r=>r.product_id===pid)||{};formModal('Product photo & publication',`<label>Product<select name="product_id">${selectOptions(S.products.filter(p=>p.kind!=='ingredient'),pid)}</select></label>${imagePicker('Product photo','asset_id',r.asset_id||'')}${field('Description','description',r.description||'')}<label class="check"><input type="checkbox" name="published" ${r.published?'checked':''}> Publish in customer catalogue</label><label class="check"><input type="checkbox" name="policy_confirmed"> I checked this genuine food/non-alcoholic drink, accurate photo, price and description against the catalogue policy.</label><div class="help">A positive retail price and a photo are required. Recheck publication after changing the product or price. Unpublished inventory remains private.</div>`,data=>mutate('catalogue_product',data,'Catalogue product saved.'))}
function catalogueSettings(){formModal('Customer catalogue',`<label class="check"><input type="checkbox" name="enabled" ${S.settings.catalogue_enabled?'checked':''}> Enable public catalogue</label>${field('Shop WhatsApp number (optional, public)','phone',S.settings.catalogue_phone||'','tel')}${imagePicker('Catalogue banner','banner',S.settings.catalogue_banner||'')}<div class="help">The number is shown publicly for shop enquiries. Order requests don’t take payment or reserve stock.</div>`,data=>mutate('catalogue_settings',data,'Catalogue settings saved.'))}
function catalogueOrder(id){const o=(S.catalogue_orders||[]).find(o=>o.id===id);if(!o)return;formModal('Order request '+esc(id),`<p>${esc(o.name)} · +${esc(o.phone)}</p><p>${JSON.parse(o.items).map(i=>esc(i.name)+' × '+i.quantity).join('<br>')}</p><p>${esc(o.note)}</p>${dropdown('Status','status',['new','contacted','fulfilled','cancelled'],o.status)}<button type="button" class="btn secondary" onclick="catalogueToBill('${esc(id)}')">Prepare bill in POS</button><div class="help">Prices and stock are checked again at checkout. This request is not a saved invoice.</div>`,data=>mutate('catalogue_order_status',{...data,id},'Request status saved.'))}
function catalogueToBill(id){window.saleTradeOrder='';const o=S.catalogue_orders.find(o=>o.id===id);if(['fulfilled','cancelled'].includes(o.status))return toast('Review the request status before preparing a bill.',true);window.saleDiscount=0;const items=JSON.parse(o.items);if(items.some(i=>!product(i.id)))return toast('An item is no longer available. Review the order.',true);cart=items.map(i=>({id:i.id,quantity:i.quantity}));window.saleParty=S.parties.find(p=>p.kind==='customer'&&String(p.phone).replace(/\D/g,'').endsWith(o.phone.slice(-10)))?.id||'';window.priceTier='retail';closeModal();navTo('billing');toast('Order loaded. Confirm customer, availability and payment before saving the bill.')}

function ordersPage(){const orders=S.trade_orders||[],maps=S.commerce_products||[],s=S.settings,owner=!S.online||S.web_user?.role==='owner';return heading('WHATSAPP TRADING','Orders from your customers.','Customers browse the native WhatsApp catalogue, send a cart and receive order updates.',owner?`<button class="btn secondary" onclick="commerceSettings()">Connect Meta catalogue</button><button class="btn" onclick="commerceMapping()">Map trading product</button>`:'')+`<div class="notice">${s.whatsapp_commerce_enabled?'Catalogue automation enabled.':'Native catalogue automation awaits setup.'} ${s.whatsapp_catalogue_id?'Catalogue '+esc(s.whatsapp_catalogue_id):'No Meta catalogue ID saved.'} ${s.whatsapp_catalogue_checked?'Connection checked '+date(s.whatsapp_catalogue_checked):'Save catalogue ID, check its Meta link, then enable automation.'}<br>Replies: MENU / SHOP opens catalogue · STATUS checks latest order · CANCEL WA-… requests cancellation. Orders use Warehouse stock. Confirmation does not reserve stock; invoicing checks it again.</div><div class="card" style="margin-top:20px">${table(['Order / customer','Estimated total','Status / invoice',''],orders.map(o=>`<tr><td>${esc(o.id)}<small>${esc(o.name)} · +${esc(o.phone)}</small></td><td>${rupee(o.total)}</td><td>${esc(o.status)}<small>${esc(o.invoice_id||'Not invoiced')}</small></td><td><button class="text-btn" onclick="tradeOrder('${esc(o.id)}')">Manage</button></td></tr>`))}</div>${owner?`<div class="card" style="margin-top:20px"><div class="card-head"><h2>Meta retailer SKU mappings</h2>${S.online?'<a class="btn secondary" href="/api/commerce-feed">Download Meta feed CSV</a>':''}</div>${table(['Meta retailer ID','Product / pack','Price tier',''],maps.map(m=>`<tr><td>${esc(m.retailer_id)}<small>Catalogue ${esc(m.catalog_id)}</small></td><td>${esc(product(m.product_id)?.name)}<small>${m.units} base units per catalogue item</small></td><td>${esc(m.price_tier)} · ${m.active?'Active':'Disabled'}</td><td><button class="text-btn" onclick="commerceMapping(${m.id})">Edit</button></td></tr>`))}<div class="help">Publish photos and confirmed prices in Photo catalogue first, map each Meta retailer ID to a trading product, then upload the exported CSV in Commerce Manager. Feed includes only mapped, published, priced trading products. Once connected and enabled, configure Commerce Manager to fetch <a href="/commerce-feed.csv" target="_blank">the scheduled feed URL</a> hourly for automatic price and availability updates. Case packs and single bottles can have separate retailer IDs.</div></div>`:''}`}
function commerceSettings(){const s=S.settings;formModal('Native WhatsApp catalogue',`${field('Owned Meta Commerce catalogue ID','catalog_id',s.whatsapp_catalogue_id)}${field('Approved order-update utility template','order_template',s.whatsapp_order_template)}<label class="check"><input type="checkbox" name="reply" ${s.whatsapp_catalogue_reply?'checked':''}> Reply automatically to MENU / CATALOGUE / SHOP</label><label class="check"><input type="checkbox" name="enabled" ${s.whatsapp_commerce_enabled?'checked':''}> Enable native catalogue and order automation</label><div class="help">In Meta Commerce Manager create/select your trading catalogue and connect it to this WhatsApp Business Account. Save its ID first, then check the connection below. Enable only after successful check and webhook subscription.</div><button type="button" class="btn secondary" onclick="checkCommerce()">Check connection & enable Meta cart</button>`,data=>mutate('commerce_settings',data,'Catalogue settings saved.'))}
async function checkCommerce(){try{await api('commerce_check');await load();toast('Catalogue linked; native cart and visibility enabled. Save automation settings.')}catch(e){toast(e.message,true)}}
function commerceMapping(id){const m=(S.commerce_products||[]).find(m=>m.id===id)||{};formModal('Map WhatsApp trading item',`${field('Meta catalogue ID','catalog_id',m.catalog_id||S.settings.whatsapp_catalogue_id)}${field('Meta product retailer ID (same as feed id)','retailer_id',m.retailer_id,'text','required')}<label>Trading product<select name="product_id">${selectOptions(S.products.filter(p=>p.kind==='stock'),m.product_id)}</select></label>${field('Base units per catalogue item (1 for a bottle)','units',m.units||1,'number','min="1" max="1000" step="1" required')}${dropdown('Price tier','price_tier',['retail','wholesale'],m.price_tier||'retail')}<label class="check"><input type="checkbox" name="active" ${m.active!==0?'checked':''}> Active for orders and export</label>`,data=>mutate('commerce_product',data,'Trading SKU mapping saved.'))}
function tradeOrder(id){const o=S.trade_orders.find(o=>o.id===id),issues=JSON.parse(o.issues);formModal('WhatsApp order '+esc(id),`<p>${esc(o.name)} · +${esc(o.phone)} · Warehouse</p>${table(['Item','Base units','Current amount'],JSON.parse(o.items).map(l=>`<tr><td>${esc(l.name)}<small>Meta SKU ${esc(l.retailer_id)} · ${l.catalogue_quantity} catalogue item(s)</small></td><td>${qty(l.quantity)}</td><td>${rupee(l.price*l.quantity)}</td></tr>`))}<p>Estimated total: <strong>${rupee(o.total)}</strong></p>${issues.length?'<div class="notice">'+issues.map(esc).join('<br>')+'</div>':''}<p>${o.invoice_id?'Invoice '+esc(o.invoice_id):'Not invoiced; stock is not reserved.'}</p>${dropdown('Next status','status',['new','confirmed','packing','ready','completed','cancelled'],o.status)}<label class="check"><input type="checkbox" name="customer_confirmed_price"> Customer explicitly agreed to any revised prices</label><button type="button" class="btn secondary" onclick="repriceTradeOrder('${esc(id)}')">Recheck mapping, price & stock</button> <button type="button" class="btn secondary" onclick="billTradeOrder('${esc(id)}')">Prepare POS invoice</button>`,data=>mutate('trade_order_status',{id,status:data.status,customer_confirmed_price:data.customer_confirmed_price==='on'},'Order status saved; customer/staff updates queued on the active sender.'))}
async function repriceTradeOrder(id){try{await mutate('trade_order_reprice',{id});closeModal();tradeOrder(id)}catch(e){toast(e.message,true)}}
async function billTradeOrder(id){const o=S.trade_orders.find(o=>o.id===id);if(o.invoice_id||!['confirmed','packing','ready'].includes(o.status)||JSON.parse(o.issues).length)return toast('Confirm and resolve this unbilled order first.',true);if(localLocation()!=='Warehouse'){if(S.online){if(S.web_user.role!=='owner')return toast('A staff account with Warehouse permissions is required.',true);await api('location',{location:'Warehouse'})}else await api('settings',{device_location:'Warehouse'});await load()}const items=JSON.parse(o.items);cart=[];for(const l of items){const old=cart.find(r=>r.id===l.product_id);if(old)old.quantity+=l.quantity;else cart.push({id:l.product_id,quantity:l.quantity})}window.saleTradeOrder=o.id;window.saleDiscount=0;window.priceTier=items[0]?.tier||'retail';window.saleParty=S.parties.find(p=>p.kind==='customer'&&String(p.phone).replace(/\D/g,'').endsWith(o.phone.slice(-10)))?.id||'';closeModal();navTo('billing');toast('Order loaded. Confirm payment and save its linked invoice.')}

iconPaths.planning=iconPaths.purchases;pages.planning='Planning & procurement';
function planningPage(){const rows=S.inventory_planning||[],orders=S.purchase_orders||[];return heading('PLAN & PURCHASE','Keep the shelves ready.','Recommendations use 30-day sales and ingredient consumption, lead time, safety stock and open purchase orders.',`<button class="btn secondary" onclick="planningPolicy()">Stock policy</button><button class="btn" onclick="purchaseOrderForm()">＋ Purchase order</button>`)+`<div class="help">Orders are estimates. Stock and supplier balances change only when goods are received and a purchase invoice is saved. Quantities are rounded to pack sizes. Without sales history, recommendations use safety stock. Café materials can be transferred from Warehouse.</div><div class="card"><div class="card-head"><h2>Stock alerts</h2></div>${table(['Alert','Details'],(S.stock_alerts||[]).map(a=>`<tr><td><span class="pill warn">${esc(a.kind.replaceAll('_',' '))}</span></td><td style="white-space:pre-line">${esc(a.message)}</td></tr>`))}</div><div class="card"><div class="card-head"><h2>Replenishment plan</h2></div>${table(['Product / location','Available / incoming','Daily use / supply','Suggested / estimated',''],rows.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.location)}</small></td><td>${qty(r.stock)} / ${qty(r.incoming)} ${esc(r.unit)}</td><td>${qty(r.daily_demand)} / ${r.days_remaining??'No history'} days</td><td>${qty(r.recommended)} ${esc(r.unit)}<small>${rupee(r.estimated_cost)}${r.transfer_available?' · transfer '+qty(r.transfer_available)+' available':''}</small></td><td><button class="text-btn" onclick="planningPolicy(${r.product_id},'${r.location}')">Policy</button>${r.recommended?`<button class="text-btn" onclick="purchaseOrderForm(${r.product_id},'${r.location}')">Order</button>`:''}</td></tr>`))}</div><div class="card"><div class="card-head"><h2>Purchase orders</h2></div>${table(['Reference','Supplier / location','Status','Estimate',''],orders.map(o=>`<tr><td>${esc(o.id)}<small>${date(o.created)}</small></td><td>${esc(party(o.supplier_id)?.name)}<small>${esc(o.location)}</small></td><td>${esc(o.status.replaceAll('_',' '))}</td><td>${rupee(o.total)}</td><td><button class="text-btn" onclick="viewPurchaseOrder('${esc(o.id)}')">Review</button></td></tr>`))}</div>`}
function planningPolicy(pid,loc='Warehouse'){const old=(S.inventory_plans||[]).find(p=>p.product_id==pid&&p.location===loc)||{};formModal('Stock planning policy',`${dropdown('Product','product_id',S.products.filter(p=>p.kind!=='recipe').map(p=>({value:p.id,label:p.name})),pid)}${dropdown('Location','location',['Warehouse','Outlet'],loc)}${dropdown('Preferred supplier','supplier_id',[{value:'',label:'Choose when ordering'},...S.parties.filter(p=>p.kind==='supplier').map(p=>({value:p.id,label:p.name}))],old.supplier_id||'')}<div class="form-grid">${field('Supplier lead time (days)','lead_days',old.lead_days??2,'number','min="0" max="365" required')}${field('Days to cover','cover_days',old.cover_days??14,'number','min="1" max="365" required')}${field('Safety stock (base units)','safety_stock',old.safety_stock??product(pid)?.minimum??0,'number','min="0" step="any" required')}</div><label class="check"><input type="checkbox" name="enabled" ${old.enabled===0?'':'checked'}> Include in replenishment planning</label>`,d=>mutate('inventory_plan',{...d,enabled:d.enabled==='on'},'Planning policy saved.'))}
function purchaseOrderForm(pid,loc='Warehouse'){if(!S.parties.some(p=>p.kind==='supplier'))return partyForm('supplier');const r=(S.inventory_planning||[]).find(r=>r.product_id==pid&&r.location===loc);formModal('Draft purchase order',`${dropdown('Supplier','supplier_id',S.parties.filter(p=>p.kind==='supplier').map(p=>({value:p.id,label:p.name})),r?.supplier_id)}${dropdown('Receive at','location',['Warehouse','Outlet'],loc)}${field('Order note','note','')}<div id="purchase-lines"></div><button type="button" class="btn secondary small" onclick="addPurchaseLine()">＋ Add item</button><div class="help" id="purchase-total"></div>`,d=>{const items=Array.from(document.querySelectorAll('.purchase-line')).map(e=>({product_id:e.querySelector('select').value,quantity:e.querySelector('[data-qty]').value,price:e.querySelector('[data-price]').value}));return mutate('purchase_order_create',{...d,items},'Draft created. No stock or supplier balance changed.')},'Save draft');addPurchaseLine();if(pid){const e=$('.purchase-line');e.querySelector('select').value=pid;e.querySelector('[data-qty]').value=r?.recommended||product(pid).pack;e.querySelector('[data-price]').value=product(pid).cost/100;purchaseTotal()}}
function viewPurchaseOrder(id){const o=S.purchase_orders.find(o=>o.id===id);openModal('Purchase order '+id,`${table(['Item','Ordered','Received','Remaining'],JSON.parse(o.items).map(i=>`<tr><td>${esc(i.name)}</td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${qty(i.received)}</td><td>${qty(i.quantity-i.received)}</td></tr>`))}<p>${esc(o.note)}</p><div class="help">Estimated ${rupee(o.total)}. Confirm actual supplier invoice costs and payment when receiving. Sync before receiving against a shared order.</div>`,`${o.status==='draft'?`<button class="btn" onclick="poStatus('${id}','approved')">Approve</button>`:''}${o.status==='approved'?`<button class="btn secondary" onclick="poStatus('${id}','sent')">Mark sent to supplier</button>`:''}${['approved','sent','part_received'].includes(o.status)?`<button class="btn" onclick="receivePurchaseOrder('${id}')">Receive goods</button>`:''}${['draft','approved','sent','part_received'].includes(o.status)?`<button class="btn danger" onclick="poStatus('${id}','cancelled')">Cancel remaining</button>`:''}<button class="btn secondary" onclick="closeModal()">Close</button>`)}
async function poStatus(id,status){try{await mutate('purchase_order_status',{id,status},'Purchase order updated.');closeModal()}catch(e){toast(e.message,true)}}
function receivePurchaseOrder(id){const o=S.purchase_orders.find(o=>o.id===id);closeModal();purchaseForm();const form=$('#modal form');form.elements.party_id.value=o.supplier_id;form.elements.location.value=o.location;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='purchase_order_id';hidden.value=id;form.appendChild(hidden);$('#purchase-lines').innerHTML='';for(const i of JSON.parse(o.items).filter(i=>i.received<i.quantity)){addPurchaseLine();const e=Array.from(document.querySelectorAll('.purchase-line')).at(-1);e.querySelector('select').value=i.product_id;e.querySelector('[data-qty]').value=i.quantity-i.received;e.querySelector('[data-price]').value=i.cost/100}purchaseTotal();toast('Receiving '+id+'. Reduce quantities for a partial delivery; enter actual supplier reference and costs.')}
function restoreForm(){formModal('Restore business backup',`<p>Restore a backup ZIP containing the database and photographs. This replaces business records after making a safety backup. Accounts on this PC are preserved; you will sign in again.</p><div class="notice">Paired or folder-synced PCs require assisted recovery to avoid replaying old transactions.</div><label>Backup ZIP<input id="restore-file" type="file" accept=".zip" required></label>${field('Type RESTORE to confirm','confirm','','text','pattern="RESTORE" required')}`,async d=>{const f=$('#restore-file').files[0];if(!f)throw Error('Choose a backup ZIP.');if(f.size>64*1024*1024)throw Error('Use assisted recovery for backups above 64 MB.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});await api('restore_bundle',{confirm:d.confirm,content});location.href='/login'},'Back up & restore')}
const baseOverview=overview;
overview=function(){const role=S.web_user?.role||'owner',tasks=role==='viewer'?[]:role==='cashier'?[['billing','New bill','Scan or choose products'],['people','Customer profiles','Find a mobile number']]:[['billing','New bill','Retail, wholesale or café'],['purchases','Receive stock','Record supplier invoice'],['planning','Plan & order','Review replenishment'],['people','Collect or pay','Customer and supplier dues']];return `<div class="task-grid">${tasks.map(([p,title,note])=>`<button class="task" onclick="navTo('${p}')"><strong>${title}</strong><span>${note}</span></button>`).join('')}</div>`+baseOverview()};
const flowRender=render;
render=function(){flowRender();if(draftLoaded)saveBillDraft();if(!$('#nav-backdrop')){const b=document.createElement('button');b.id='nav-backdrop';b.className='nav-backdrop';b.setAttribute('aria-label','Close navigation');b.onclick=()=>$('.sidebar').classList.remove('open');document.body.appendChild(b)}if(!$('#mobile-menu')){const b=document.createElement('button');b.id='mobile-menu';b.className='btn secondary small menu-button';b.style.display='none';b.textContent='☰ Menu';b.setAttribute('aria-label','Open navigation');b.onclick=()=>$('.sidebar').classList.toggle('open');$('header').prepend(b)}const d=S.diagnostics||{},errors=S.sync_errors.length,mode=S.online?'Online workspace':S.settings.cloud_url?'Server sync':S.settings.sync_folder?'Folder exchange':'Local PC';const status=document.createElement('div');status.className='system-status'+(errors?' warn':'');status.innerHTML=`<strong>${esc(mode)}${errors?' · '+errors+' conflict(s) need review':''}</strong><span>${S.online?'Internet required':'Billing works offline'}</span><span>${d.pending_sync!=null?d.pending_sync+' changes waiting to sync':''}</span><span>${S.release_version?'v'+esc(S.release_version):''}</span><span>${(d.background_tasks||[]).filter(t=>t.failures>0).map(t=>esc(t.component)+' needs attention').join(' · ')}</span>`;$('#main').prepend(status)};
const flowNav=navTo;navTo=function(name){$('.sidebar').classList.remove('open');const role=S?.web_user?.role;if(role==='cashier'&&!['overview','billing','people','staff'].includes(name))return toast('This screen requires a manager or owner account.',true);if(role==='viewer'&&!['overview','people','staff'].includes(name))return toast('Your account is read-only.',true);flowNav(name)};

function billDraftKey(){return 'alhadiya-bill:'+S.settings.device_id+':'+(S.web_user?.id||'local')}
function saveBillDraft(){try{if(!cart.length){sessionStorage.removeItem(billDraftKey());return}sessionStorage.setItem(billDraftKey(),JSON.stringify({cart,party:window.saleParty||'',tier:window.priceTier||'retail',discount:window.saleDiscount||0,order:window.saleTradeOrder||'',location:localLocation()}))}catch{}}
function restoreBillDraft(){try{const d=JSON.parse(sessionStorage.getItem(billDraftKey())||'null');if(!d||d.location!==localLocation())return;if(d.order&&!S.trade_orders.some(o=>o.id===d.order&&!o.invoice_id)){sessionStorage.removeItem(billDraftKey());toast('Saved order draft cleared because the order is already invoiced or unavailable.');return}cart=d.cart.filter(l=>product(l.id)&&Number.isFinite(l.quantity)&&l.quantity>0);window.saleParty=S.parties.some(p=>p.id==d.party)?d.party:'';window.priceTier=d.tier==='wholesale'?'wholesale':'retail';window.saleDiscount=Math.max(0,Number(d.discount)||0);window.saleTradeOrder=S.trade_orders.some(o=>o.id===d.order&&!o.invoice_id)?d.order:'';if(cart.length)toast('Unfinished bill restored. Review current prices and stock before checkout.')}catch{}}

const policyNotifications=notificationsPage;notificationsPage=function(){return (S.settings.whatsapp_pause_reason?'<div class="notice">'+esc(S.settings.whatsapp_pause_reason)+'</div>':'')+policyNotifications()};

function disconnectServerForm(){formModal('Disconnect server sync','<p>Stop billing on every node and exchange all changes first. This PC verifies a final exchange and makes a backup. Keep the same business data on every node before switching to a shared folder. Do not use this for a temporary server shutdown.</p>'+field('Type DISCONNECT','confirm','','text','pattern="DISCONNECT" required'),d=>mutate('cloud_disconnect',d,'Server exchange finished. Configure folder exchange if needed.'),'Finish exchange & disconnect')}

async function openCafePOS(){if(localLocation()!=='Outlet'){if(cart.length)return toast('Finish or clear the current bill before switching to the café.',true);if(S.web_user?.role!=='owner')return toast('Select an account assigned to the café outlet, or ask the owner to change your access.',true);try{await api('location',{location:'Outlet'});window.saleParty='';window.saleDiscount=0;await load()}catch(e){return toast(e.message,true)}}navTo('billing');category='Café menu';render()}
